import sys

data = list(map(int, sys.stdin.buffer.read().split()))
L, C = data[0], data[1]
P = data[2]

black = set()
index = 3
for _ in range(P):
    x, y = data[index] - 1, data[index + 1] - 1
    black.add((x, y))
    index += 2

directions = ((1, 0), (-1, 0), (0, 1), (0, -1))
candidates = set()

for x, y in black:
    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < L and 0 <= ny < C and (nx, ny) not in black:
            candidates.add((nx, ny))

left = [cell for cell in candidates if (cell[0] + cell[1]) % 2 == 0]
adj = {}

for x, y in left:
    neighbors = []
    for dx, dy in directions:
        cell = (x + dx, y + dy)
        if cell in candidates:
            neighbors.append(cell)
    adj[(x, y)] = neighbors

matched = {}

def augment(cell, seen):
    for neighbor in adj[cell]:
        if neighbor in seen:
            continue
        seen.add(neighbor)
        if neighbor not in matched or augment(matched[neighbor], seen):
            matched[neighbor] = cell
            return True
    return False

matching = 0
for cell in left:
    if augment(cell, set()):
        matching += 1

print(len(candidates) - matching)
